detail-btn" data-id="<?=$l['id']?>">Details</button><?php if($l['requirement_file']):?><a class="btn btn-outline-secondary btn-sm" href="index.php?page=benefits_loan_requirement&loan_id=<?=$l['id']?>">File</a><?php endif;?><?php if(!$isHRAdmin&&$l['status']==='Returned'):?><button class="btn btn-warning btn-sm resubmit-btn" data-json='<?=htmlspecialchars(json_encode($l),ENT_QUOTES)?>'>Resubmit</button><?php endif;?><?php if($isHRAdmin&&in_array($l['status'],['Submitted','Under Review','Approved','Released'],true)):?><button class="btn btn-success btn-sm review-btn" data-json='<?=htmlspecialchars(json_encode($l),ENT_QUOTES)?>'>Process</button><?php endif;?><?php if($isHRAdmin&&$l['status']==='Active'):?><button class="btn btn-info btn-sm payment-btn" data-id="<?=$l['id']?>" data-balance="<?=$l['balance_remaining']?>">Payment</button><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div><?php if(!$loans):?><div class="text-center py-5 text-secondary"><i class="fa-solid fa-receipt fa-2x mb-2"></i><p>No loan records found.</p></div><?php endif;?></div></div>
