<script>$(function(){const csrf='<?=csrf_token()?>',send=(url,form)=>$.ajax({url,type:'POST',data:form,processData:!(form instanceof FormData),contentType:form instanceof FormData?false:'application/x-www-form-urlencoded',dataType:'json'}).done(r=>{if(r.status==='success'){showToast('success',r.message);setTimeout(()=>location.reload(),700)}else Swal.fire('Error',r.message,'error')}).fail(x=>Swal.fire('Error',x.responseJSON?.message||'Request failed.','error'));$('#applyForm').submit(function(e){e.preventDefault();send('index.php?page='+($('#applyLoanId').val()?'benefits_loan_resubmit':'benefits_request_loan'),new FormData(this))});$('.resubmit-btn').click(function(){let l=$(this).data('json');$('#applyLoanId').val(l.id);$('#applyProgram').val(l.loan_program_id).prop('disabled',true);$('#applyAmount').val(l.requested_amount);$('#applyTerm').val(l.term_months);$('#applyNotes').val(l.application_notes);bootstrap.Modal.getOrCreateInstance('#applyModal').show()});$('#applyModal').on('hidden.bs.modal',()=>{$('#applyLoanId').val('');$('#applyProgram').prop('disabled',false)});$('#programForm').submit(function(e){e.preventDefault();send('index.php?page=loan_program_save',$(this).serialize())});$('.toggle-program').click(function(){send('index.php?page=loan_program_toggle',{id:$(this).data('id'),csrf_token:csrf})});$('.edit-program').click(function(){let p=$(this).data('json');for(const [k,v] of Object.entries({programId:p.id,programName:p.name,programDescription:p.description,programMax:p.maximum_amount,programRate:p.interest_rate,programMinTerm:p.minimum_term_months,programMaxTerm:p.maximum_term_months,programTenure:p.minimum_tenure_months,programStatuses:p.eligible_employment_statuses,programRules:p.eligibility_rules,programDocs:p.required_documents,programDepartments:p.eligible_department_ids}))$('#'+k).val(v);bootstrap.Modal.getOrCreateInstance('#programModal').show()});let transitions={'Submitted':['Under Review','Returned','Approved','Rejected','Cancelled'],'Under Review':['Returned','Approved','Rejected'],'Approved':['Released','Cancelled'],'Released':['Active']};$('.review-btn').click(function(){let l=$(this).data('json');$('#reviewId').val(l.id);$('#approvedAmount').val(l.requested_amount);$('#reviewStatus').html((transitions[l.status]||[]).map(s=>`<option>${s}</option>`));bootstrap.Modal.getOrCreateInstance('#reviewModal').show()});$('#reviewForm').submit(function(e){e.preventDefault();send('index.php?page=admin_update_loan_status',$(this).serialize())});$('.payment-btn').click(function(){let b=$(this).data('balance');$('#paymentId').val($(this).data('id'));$('#paymentBalance').text(Number(b).toLocaleString());$('#paymentAmount').attr('max',b);bootstrap.Modal.getOrCreateInstance('#paymentModal').show()});$('#paymentForm').submit(function(e){e.preventDefault();send('index.php?page=benefits_loan_payment',$(this).serialize())});$('.detail-btn').click(function(){
 const id=$(this).data('id'),money=v=>'PHP '+Number(v||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2}),esc=v=>$('<div>').text(v??'').html();
 bootstrap.Modal.getOrCreateInstance('#detailModal').show();
 $('#loanDetailSubtitle').text('Loading loan information…');
 $('#detailBody').html('<div class="loan-detail-loading"><span class="spinner-border spinner-border-sm"></span><span>Loading payment information…</span></div>');
 $.getJSON('index.php?page=benefits_loan_detail&loan_id='+id).done(r=>{
  if(r.status!=='success'){showErrorDialog(r.message||'Unable to load loan information.');return}
  const l=r.data.loan||{},s=r.data.schedule||[],p=r.data.payments||[],paid=p.reduce((sum,x)=>sum+Number(x.amount||0),0),status=esc(l.status||'Unknown');
  $('#loanDetailSubtitle').text((l.program_name||l.loan_type||'Loan')+' · '+(l.employee_code||'Employee record'));
  const scheduleRows=s.length?s.map(x=>{const state=String(x.status||'Pending'),tone=state==='Paid'?'success':(state==='Partial'?'warning':'secondary');return '<tr><td><span class="loan-installment-no">'+x.installment_no+'</span></td><td>'+esc(x.due_date)+'</td><td><strong>'+money(x.amount_due)+'</strong></td><td>'+money(x.amount_paid)+'</td><td><span class="badge badge-soft-'+tone+'">'+esc(state)+'</span></td></tr>'}).join(''):'<tr><td colspan="5"><div class="loan-detail-empty"><i class="fa-regular fa-calendar-xmark"></i><span>No payment schedule generated yet.</span></div></td></tr>';
  const history=p.length?p.map(x=>'<div class="loan-payment-entry"><span class="loan-payment-icon"><i class="fa-solid fa-receipt"></i></span><span class="loan-payment-copy"><strong>'+money(x.amount)+'</strong><small>'+esc(x.payment_method)+' · '+esc(x.payment_date)+(x.reference_no?' · Ref '+esc(x.reference_no):'')+'</small></span><span class="badge badge-soft-success">Recorded</span></div>').join(''):'<div class="loan-detail-empty"><i class="fa-regular fa-folder-open"></i><span>No payments recorded.</span></div>';
  $('#detailBody').html('<div class="loan-detail-summary"><div><span>Total payable</span><strong>'+money(l.total_payable)+'</strong></div><div><span>Total paid</span><strong>'+money(paid)+'</strong></div><div><span>Remaining balance</span><strong>'+money(l.balance_remaining)+'</strong></div><div><span>Loan status</span><strong><span class="badge badge-soft-'+(l.status==='Paid'?'success':'primary')+'">'+status+'</span></strong></div></div><section class="loan-detail-section"><div class="loan-detail-section-heading"><div><span class="loan-detail-section-icon"><i class="fa-regular fa-calendar"></i></span><div><h6>Payment schedule</h6><small>'+s.length+' installment'+(s.length===1?'':'s')+'</small></div></div></div><div class="table-responsive"><table class="table loan-schedule-table"><thead><tr><th>#</th><th>Due date</th><th>Due amount</th><th>Paid</th><th>Status</th></tr></thead><tbody>'+scheduleRows+'</tbody></table></div></section><section class="loan-detail-section"><div class="loan-detail-section-heading"><div><span class="loan-detail-section-icon"><i class="fa-solid fa-clock-rotate-left"></i></span><div><h6>Payment history</h6><small>'+p.length+' recorded transaction'+(p.length===1?'':'s')+'</small></div></div></div><div class="loan-payment-history">'+history+'</div></section>');
 }).fail(x=>{$('#detailBody').html('<div class="loan-detail-empty is-error"><i class="fa-solid fa-circle-exclamation"></i><span>Unable to load payment information.</span></div>');showErrorDialog(x.responseJSON?.message||'Unable to load loan information.')});
});$('#statusFilter').change(function(){let t=$('#loansTable').DataTable();t.column(<?=$isHRAdmin?5:4?>).search(this.value).draw()})});</script>
